items:
for arg in "$@"; do
	case "$arg" in
		--replay) REPLAY=true ;;
		-h|--help) sed -n '2,25p' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
		*) UPSTREAM="$arg" ;;
	esac
done

nvm_has_executable() {
	(
		# `|| true` so that shells with errexit-style options (eg, zsh's ERR_RETURN)
		# do not abort the subshell when the name is not an alias or a function
		unalias "${1-}" 2>/dev/null || true
		unset -f "${1-}" 2>/dev/null || true
		command -v "${1-}" > /dev/null 2>&1
	)
}

nvm_is_wsl() {
	if [ -e /proc/sys/fs/binfmt_misc/WSLInterop ] || [ -e /proc/sys/fs/binfmt_misc/WSLInterop-late ]; then
		return 0
	fi
	case "$(command uname -r 2>/dev/null)" in
		*[Mm]icrosoft*) return 0 ;;
	esac
	return 1
}

if [ -z "${PREV_REF}" ]; then
	PREV_REF="$(git describe --abbrev=0 --tags --match 'v[0-9]*.[0-9]*.[0-9]*')" || {
		printf >&2 'release-notes: failed to determine the previous version tag.\n'
		exit 1
	}
fi

symbols() {
	"$1" --defined-only -g "$2" 2>/dev/null |
		awk 'NF == 3 { print $3 }' |
		grep '^uv_[^_]' |
		sort -u
}

host() {
	case "$TRAVIS_OS_NAME" in
		linux)
			echo x86_64-unknown-linux-gnu
			;;
		osx)
			echo x86_64-apple-darwin
			;;
	esac
}

gcc_prefix() {
	case "$(architecture)" in
		armhf)
			echo arm-linux-gnueabihf-
			;;
		*)
			return
			;;
	esac
}

is_musl() {
	case "$TARGET" in
		*-musl) return 0 ;;
		*)      return 1 ;;
	esac
}

is_arm() {
	case "$(architecture)" in
		armhf) return 0 ;;
		*)     return 1 ;;
	esac
}

is_linux() {
	case "$TRAVIS_OS_NAME" in
		linux) return 0 ;;
		*)     return 1 ;;
	esac
}

is_osx() {
	case "$TRAVIS_OS_NAME" in
		osx) return 0 ;;
		*)   return 1 ;;
	esac
}

_busted_comp() {
	local opt IFS=' '$'\t'$'\n'
	for opt in $1; do
		case $opt in
			--*=*) printf %s$'\n' "$opt"  ;;
			*.)    printf %s$'\n' "$opt"  ;;
			*)     printf %s$'\n' "$opt " ;;
		esac
	done
}

nvm_try_profile() {
	if [ -z "${1-}" ] || [ ! -f "${1}" ]; then
		return 1
	fi
	nvm_echo "${1}"
}

nvm_reset() {
	unset -f nvm_has nvm_has_executable nvm_install_dir nvm_latest_version nvm_profile_is_bash_or_zsh \
		nvm_source nvm_node_version nvm_download install_nvm_from_git nvm_install_node \
		install_nvm_as_script nvm_try_profile nvm_detect_profile nvm_is_wsl nvm_check_global_modules \
		nvm_do_install nvm_reset nvm_default_install_dir nvm_grep nvm_profile_has_line
}

assert_ok() {
	local FUNCTION=$1
	shift

	"$FUNCTION" "$@" || die '"'"$FUNCTION $@"'" should have succeeded, but failed'
}

assert_not_ok() {
	local FUNCTION=$1
	shift

	! "$FUNCTION" "$@" || die '"'"$FUNCTION $@"'" should have failed, but succeeded'
}

make_echo() {
	echo "#!/bin/sh" > "$1"
	echo "echo \"${2}\"" >> "$1"
	chmod a+x "$1"
}

watch() {
	$@ &
	local JOB
	JOB=$!
	while true; do sleep 15; >&2 echo '* ping *'; done &
	wait $JOB;
	local EXIT_CODE
	EXIT_CODE=$?
	kill %2;
	return $EXIT_CODE
}

nvm_profile_has_line() {
	# a commented-out line sources nothing, so it must not count as already present
	command sed 's/^[[:space:]]*#.*//' "$1" | nvm_grep -q "$2"
}

nvm_profile_is_bash_or_zsh() {
	local TEST_PROFILE
	TEST_PROFILE="${1-}"
	case "${TEST_PROFILE-}" in
		*"/.bashrc" | *"/.bash_profile" | *"/.zshrc" | *"/.zprofile")
			return
		;;
		*)
			return 1
		;;
	esac
}

case "${NEW_VERSION}" in
	v*) ;;
	*) NEW_VERSION="v${NEW_VERSION}" ;;
esac

nvm_json_throw() {
	nvm_err "$*"
	exit 1
}

nvm_make_alias() {
	# prevent local alias creation
	return 0
}

nvm_get_remote_aliases() {
	# prevent local aliases from leaking into `nvm ls-remote` mocks
	return 0
}

nvm_has_italics() {
	# keep mocks independent of the local terminal's italics support
	return 0
}

nvm_has() {
	type "$1" > /dev/null 2>&1
}

nvm_echo() {
	command printf %s\\n "$*" 2>/dev/null
}

nvm_grep() {
	GREP_OPTIONS='' command grep "$@"
}

nvm_default_install_dir() {
	[ -z "${XDG_CONFIG_HOME-}" ] && printf %s "${HOME}/.nvm" || printf %s "${XDG_CONFIG_HOME}/nvm"
}

nvm_latest_version() {
	nvm_echo "v0.41.0"
}

nvm_node_version() {
	nvm_echo "$NODE_VERSION"
}

case "${NPM_COMMAND}" in
	*/*) nvm_is_wsl && [ -f "${NPM_COMMAND%/*}/npm.cmd" ] && return 0 ;;
esac

find_name(){
	find test -name "*[\\/:\*\?\"<>\|]*" -o -name "*."
}

try() {
	CAPTURED_STDOUT="$(set +x; "$@" 2>/dev/null)" && CAPTURED_EXIT_CODE=0 || CAPTURED_EXIT_CODE=$?
}

try_err() {
	CAPTURED_STDERR="$(set +x; "$@" 2>&1 >/dev/null)" && CAPTURED_EXIT_CODE=0 || CAPTURED_EXIT_CODE=$?
}

nvm_is_version_installed() {
	return 1
}

nvm_lts_status_path() {
	nvm_echo "$MOCKS_DIR/nodejs.org-dist-lts-status.txt"
}

architecture() {
	case "$TARGET" in
		x86_64-*)
			echo amd64
			;;
		i686-*|i586-*|i386-*)
			echo i386
			;;
		arm*-unknown-linux-gnueabihf)
			echo armhf
			;;
		*)
			die "architecture: unexpected target $TARGET"
			;;
	esac
}

for NVM_DOWNLOAD_WGET_ARG in "$@"; do
	if [ "${NVM_DOWNLOAD_WGET_SKIP}" = '1' ]; then
		NVM_DOWNLOAD_WGET_SKIP=0
		continue
	fi
	case "${NVM_DOWNLOAD_WGET_ARG}" in
		'--progress-bar') set -- "$@" '--progress=bar' ;;
		'--compressed') : ;;
		'--fail') : ;;
		'-L') : ;;
		'-I') set -- "$@" '--server-response' ;;
		'-s') set -- "$@" '-q' ;;
		'-sS') set -- "$@" '-nv' ;;
		'-o') set -- "$@" '-O' ;;
		'-C') NVM_DOWNLOAD_WGET_SKIP=1; set -- "$@" '-c' ;;
		*) set -- "$@" "${NVM_DOWNLOAD_WGET_ARG}" ;;
	esac
done
